// Rules connect explicit intake selections, scoped direction responses and official requirements.
// A context difference is descriptive; only mutually exclusive claims in the same context conflict.
import {startingQuestions,selections} from '../combined/starting-point.js';
import tracks from '../v3/bank.json' with {type:'json'};
const T=(en,zh,ms)=>[en,zh,ms];
const label=(q,id)=>q?.options?.find(o=>o.id===id)?.label;
export function buildPersonalModel(a,intake){
 const answers=intake?.answers||{},questions=startingQuestions(answers),q=id=>questions.find(q=>q.id===id),values=id=>selections(answers[id]);
 const labels=id=>values(id).map(v=>({id:v,label:label(q(id),v)})).filter(x=>x.label);
 const concerns=labels('Q02'),primary=concerns.find(c=>c.id===answers.Q02?.primary)||null;
 const interests=labels('Q12'),experience=labels('Q06'),barriers=labels('Q07'),goals=labels('Q08'),background=labels('Q04');
 const role=a.roles[0],beginner=!values('Q06').some(id=>['C','D','E','W','F'].includes(id))&&a.dimensions.experience.status!=='reported';
 const phase=values('Q06').includes('E')?'internship':values('Q06').includes('W')?'work':values('Q06').some(id=>['C','D','F'].includes(id))?'project':'learning';
 const phaseLabels={learning:T('Learning and exploration','学习与探索阶段','Pembelajaran dan penerokaan'),project:T('Personal and team projects','个人作品与团队项目','Projek peribadi dan pasukan'),internship:T('Internship experience to build on','把实习经历转化为发展优势','Pengalaman latihan industri untuk dikembangkan'),work:T('Professional experience to transfer','迁移已有职业经验','Pengalaman profesional untuk dipindahkan')};
 const next=values('Q07').includes('G')?{rule:'resource-aware',title:T('Start with a low-cost, focused experiment','从低成本的重点实践开始','Mulakan eksperimen fokus berkos rendah'),task:role.project,why:T('You selected resource constraints. Use public material and a short session to test this occupational task before investing in a longer course.','你选择了资源限制。先用公开资料和一个短练习体验这项职业任务，再决定是否投入长期课程。','Anda memilih kekangan sumber. Gunakan bahan awam dan sesi singkat sebelum melabur dalam kursus panjang.'),evidenceIds:['Q07',a.direction+'01',a.direction+'02']}:
 values('Q08').includes('E')||answers.Q01==='E'?{rule:'transition',title:T('Test a transfer before committing to a career change','先验证一次能力迁移，再决定转型','Uji pemindahan sebelum pertukaran kerjaya'),task:role.project,why:T('You are considering a transition. Compare this task’s requirements with the experience and fields you selected; preserve your existing strengths while testing the unfamiliar part.','你正在考虑转型。把这项任务的要求与已选领域、经历进行比较，保留已有优势，重点试验陌生部分。','Anda mempertimbangkan peralihan. Bandingkan keperluan tugas dengan bidang dan pengalaman dipilih, sambil menguji bahagian baharu.'),evidenceIds:['Q01','Q04','Q06','Q08']}:
 beginner?{rule:'learner',title:T('Discover the work through a guided learning project','用有指导的学习项目认识职业','Kenali tugas melalui projek pembelajaran berpandu'),task:role.project,why:T('Your starting point is learning. A tutorial, classroom exercise or small personal experiment is a valid next step; formal work experience is not a prerequisite.','你的起点在学习阶段。教程、课堂练习或个人小实验都可以作为下一步，不需要先有正式工作经历。','Titik permulaan anda ialah pembelajaran. Tutorial, latihan kelas atau eksperimen peribadi kecil sesuai; pengalaman kerja rasmi bukan prasyarat.'),evidenceIds:['Q01','Q05','Q06',a.direction+'05',a.direction+'06']}:
 {rule:phase,title:phase==='internship'?T('Turn an internship contribution into a clear case','把一次实习贡献整理成具体案例','Jadikan sumbangan latihan industri sebagai kes jelas'):T('Extend an existing result toward this role','把已有成果向目标职业延伸','Kembangkan hasil sedia ada ke arah peranan ini'),task:role.project,why:T('You selected practical experience. Reuse a suitable project or contribution and test one requirement from this role, with a clear quality criterion and feedback.','你选择了实践经历。可以复用合适的项目或贡献，围绕该职业的一项要求增加清晰的质量标准与反馈。','Anda memilih pengalaman praktikal. Guna semula projek sesuai dan uji satu keperluan peranan dengan kriteria kualiti serta maklum balas.'),evidenceIds:['Q06',a.direction+'05',a.direction+'06']};
 const preference=a.dimensions.interest.status==='reported'?T('You are drawn to the actual tasks in this direction.','你对这一方向的具体任务有明确兴趣。','Anda berminat dengan tugas sebenar dalam arah ini.'):a.dimensions.interest.status==='limited'?T('Use a short task comparison to test whether this direction deserves more of your time.','用短任务比较检验这一方向是否值得继续投入。','Gunakan perbandingan tugas ringkas untuk menguji arah ini.'):T('Your task preferences are exploratory; compare the two routes before narrowing your choice.','你的任务偏好仍在探索中，适合先比较两条路线再聚焦。','Keutamaan tugas anda masih diteroka; bandingkan dua laluan dahulu.');
 return {version:'personal-context-2',primary,concerns,interests,experience,barriers,goals,background,phase,phaseLabel:phaseLabels[phase],beginner,next,preference,stage:label(q('Q01'),answers.Q01),markets:labels('Q09'),primaryMarket:label(q('Q09'),answers.Q09?.primary),evidenceIds:['Q01','Q02','Q04','Q05','Q06','Q07','Q08','Q09','Q12'],directionLabel:tracks.tracks.find(t=>t.id===a.direction)?.label};
}
export function buildAIEvidence(evidence,intake,roles,direction){
 const selected=selections(intake?.answers.Q13),has=id=>selected.includes(id),find=id=>evidence.find(e=>e.id===id),value=id=>Number.isInteger(find(id)?.raw)?find(id).raw:null;
 const context=startingQuestions(intake?.answers||{}).find(q=>q.id==='Q13');
 const modes=selected.filter(id=>!['understand','none'].includes(id)).map(id=>({id,label:label(context,id),evidenceIds:['Q13'],basis:'reported'}));
 const role=roles[0],roleReq=role.requirements.slice(0,3),daily=value('G03'),professional=value(direction+'07'),generalCheck=value('G04'),taskCheck=value(direction+'08');
 const make=(id,reported,inferred,ids,task)=>({id,mode:reported?'reported':inferred?'inferred':'explore',evidenceIds:ids.filter(id=>find(id)&&!find(id).missing),verified:false,task,requirements:roleReq.map(r=>({id:r.id,label:r.label,sourceId:r.sourceId})),rule:'ai-context-map-2:'+id});
 const ai=[
 make('awareness',has('understand'),has('check')||generalCheck>=5,['Q13','G04'],T('Explain one limitation of AI on the selected occupational task, and identify where a human decision is needed.','结合所选职业任务说明 AI 的一项局限，并找出需要人类决策的环节。','Terangkan satu batasan AI pada tugas dipilih dan tempat keputusan manusia diperlukan.')),
 make('usage',modes.length>0||daily>=5,professional>=5,['Q13','G03',direction+'07'],role.project),
 make('verification',has('check'),generalCheck>=5||taskCheck>=5,['Q13','G04',direction+'08'],T('Check one important output against the original source or an independent test. Use the role’s quality requirement as your checklist.','对照原始来源或独立测试核查一项重要输出，把职业质量要求作为检查清单。','Semak satu hasil penting dengan sumber asal atau ujian bebas menggunakan keperluan kualiti peranan.')),
 make('workflow',has('workflow')||has('automate')||has('api'),professional>=5,['Q13',direction+'07'],T('Map the steps of this occupational task. Choose one AI-assisted step and define the human review before the next step.','画出这项职业任务的步骤，选一个 AI 辅助环节，并明确进入下一步之前的人工复核。','Petakan langkah tugas ini. Pilih satu langkah bantuan AI dan tetapkan semakan manusia sebelum langkah seterusnya.')),
 make('development',has('api')||has('automate'),false,['Q13'],T('If useful for your target role, connect two existing tools in a small workflow and test its failure cases before attempting a custom AI application.','如果目标职业需要，可先用现有工具连接一个小流程并测试失败情况，再考虑定制 AI 应用。','Jika relevan kepada peranan, sambungkan dua alat dalam aliran kecil dan uji kegagalan sebelum aplikasi AI tersuai.'))
 ];
 const contrast=daily>=5&&professional!==null&&professional<=3?{rule:'daily-domain-difference',evidenceIds:['G03',direction+'07'],copy:T('You use AI actively in everyday tasks, while applying it to this professional workflow is a useful next development step.','你在日常 AI 使用方面较为积极，专业工作流应用则是值得继续发展的下一步。','Anda aktif menggunakan AI harian; aplikasi dalam aliran profesional ialah langkah pembangunan seterusnya.')}:
 professional>=5&&daily!==null&&daily<=3?{rule:'focused-domain-use',evidenceIds:['G03',direction+'07'],copy:T('Your AI use appears more focused on this professional task than on everyday use. Build on that specific context.','你的 AI 使用更集中于这类专业任务，可以从这一具体情境继续发展。','Penggunaan AI anda lebih tertumpu pada tugas profesional ini berbanding penggunaan harian.')}:
 {rule:'usage-check-relation',evidenceIds:['G03','G04',direction+'07',direction+'08'],copy:generalCheck>=5||taskCheck>=5?T('Your answers emphasise checking important AI outputs. Apply that habit to the occupational task you want to explore.','你的回答强调核查重要 AI 输出，可以把这一习惯应用到目标职业任务中。','Jawapan anda menekankan semakan hasil AI penting. Gunakan amalan itu dalam tugas sasaran.'):T('Pair your next AI-assisted task with one clear quality check, so you can judge whether the assistance is useful.','下一次使用 AI 完成任务时，加入一项清晰的质量检查，判断辅助是否真正有用。','Padankan tugas bantuan AI seterusnya dengan semakan kualiti jelas untuk menilai kegunaannya.')};
 const headline=has('none')&&!(daily>=5)?T('Start with one useful AI task.','从一项有用的 AI 任务开始。','Mulakan satu tugas AI yang berguna.'):
 has('api')||has('automate')?T('You are building AI into working systems.','你正在把 AI 接入实际系统。','Anda sedang mengintegrasi AI dalam sistem kerja.'):
 has('workflow')||professional>=5?T('Your next advantage is a clearer AI workflow.','用更清晰的 AI 工作流积累优势。','Kelebihan seterusnya ialah aliran AI lebih jelas.'):
 T('Connect your everyday AI use to real work.','把日常 AI 使用连接到真实工作。','Hubungkan penggunaan AI harian dengan kerja sebenar.');
 const contradictions=has('none')&&daily>=5?[{rule:'never-used-vs-past-month',dimension:'ai_practice',evidenceIds:['Q13','G03'],copy:T('The starting questionnaire says AI has never been used, while the past-month question reports active use. Revisit those two answers; both originals are retained.','起点问卷选择了从未使用 AI，最近一个月的题目却选择积极使用。请复看这两项回答，原始答案均保留。','Soal selidik permulaan menyatakan AI belum pernah digunakan, tetapi soalan bulan lalu menyatakan penggunaan aktif. Semak dua jawapan; kedua-duanya dikekalkan.') }]:[];
 return {ai,modes,contrast,headline,contradictions,version:'ai-context-map-2',daily,professional,generalCheck,taskCheck};
}
